/* Starry Night Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="starry-night-light"] {
  --background: rgb(248, 248, 248);
  --foreground: rgb(28, 35, 56);
  --card: rgb(227, 232, 238);
  --card-foreground: rgb(28, 35, 56);
  --popover: rgb(255, 252, 238);
  --popover-foreground: rgb(28, 35, 56);
  --primary: rgb(57, 90, 161);
  --primary-foreground: rgb(255, 252, 238);
  --secondary: rgb(249, 201, 112);
  --secondary-foreground: rgb(28, 35, 56);
  --muted: rgb(229, 229, 222);
  --muted-foreground: rgb(57, 90, 161);
  --accent: rgb(111, 163, 192);
  --accent-foreground: rgb(255, 252, 238);
  --destructive: rgb(45, 29, 47);
  --destructive-foreground: rgb(255, 252, 238);
  --border: rgb(174, 185, 196);
  --input: rgb(111, 163, 192);
  --ring: rgb(249, 201, 112);
  --chart-1: rgb(57, 90, 161);
  --chart-2: rgb(249, 201, 112);
  --chart-3: rgb(111, 163, 192);
  --chart-4: rgb(174, 185, 196);
  --chart-5: rgb(45, 29, 47);
  --radius: 0.5rem;
  --sidebar: rgb(227, 232, 238);
  --sidebar-foreground: rgb(28, 35, 56);
  --sidebar-primary: rgb(57, 90, 161);
  --sidebar-primary-foreground: rgb(255, 252, 238);
  --sidebar-accent: rgb(249, 201, 112);
  --sidebar-accent-foreground: rgb(28, 35, 56);
  --sidebar-border: rgb(174, 185, 196);
  --sidebar-ring: rgb(249, 201, 112);
  --font-sans: Libre Baskerville, serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    "Courier New", monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

