  --background: rgb(24, 26, 36);
  --foreground: rgb(232, 235, 242);
  --card: rgb(35, 36, 58);
  --card-foreground: rgb(232, 235, 242);
  --popover: rgb(35, 36, 58);
  --popover-foreground: rgb(254, 224, 107);
  --primary: rgb(57, 90, 161);
  --primary-foreground: rgb(254, 224, 107);
  --secondary: rgb(254, 224, 107);
  --secondary-foreground: rgb(35, 36, 58);
  --muted: rgb(35, 36, 58);
  --muted-foreground: rgb(121, 135, 159);
  --accent: rgb(190, 206, 239);
  --accent-foreground: rgb(24, 26, 36);
  --destructive: rgb(161, 75, 109);
  --destructive-foreground: rgb(254, 224, 107);
  --border: rgb(46, 47, 63);
  --input: rgb(57, 90, 161);
  --ring: rgb(254, 224, 107);
  --chart-1: rgb(57, 90, 161);
  --chart-2: rgb(254, 224, 107);
  --chart-3: rgb(111, 163, 192);
  --chart-4: rgb(121, 135, 159);
  --chart-5: rgb(161, 75, 109);
  --radius: 0.5rem;
  --sidebar: rgb(35, 36, 58);
  --sidebar-foreground: rgb(232, 235, 242);
  --sidebar-primary: rgb(57, 90, 161);
  --sidebar-primary-foreground: rgb(254, 224, 107);
  --sidebar-accent: rgb(254, 224, 107);
  --sidebar-accent-foreground: rgb(35, 36, 58);
  --sidebar-border: rgb(46, 47, 63);
  --sidebar-ring: rgb(254, 224, 107);
  --font-sans: Libre Baskerville, serif;
